Here's the complete solution:

```tsx
"use client"

import { useRef, type ReactNode, type AnchorHTMLAttributes, type ButtonHTMLAttributes } from "react"

type BaseProps = {
  children: ReactNode
  strength?: number
  disabled?: boolean
}

type AnchorProps = BaseProps & AnchorHTMLAttributes<HTMLAnchorElement> & { href: string }
type ButtonProps = BaseProps & ButtonHTMLAttributes<HTMLButtonElement> & { href?: never }

type MagneticButtonProps = AnchorProps | ButtonProps

export function MagneticButton({ children, strength = 0.12, disabled, ...rest }: MagneticButtonProps) {
  const ref = useRef<HTMLElement>(null)

  function onMouseMove(e: React.MouseEvent) {
    if (disabled) return
    const el = ref.current
    if (!el) return
    const rect = el.getBoundingClientRect()
    const x = e.clientX - rect.left - rect.width / 2
    const y = e.clientY - rect.top - rect.height / 2
    el.style.transform = `translate(${x * strength}px, ${y * strength}px)`
  }

  function onMouseLeave(e: React.MouseEvent) {
    const el = ref.current
    if (!el) return
    el.style.transform = "translate(0, 0)"
    ;(rest as AnchorHTMLAttributes<HTMLAnchorElement>).onMouseLeave?.(e as React.MouseEvent<HTMLAnchorElement>)
  }

  const disabledStyle: React.CSSProperties = disabled
    ? { opacity: 0.4, cursor: "not-allowed", pointerEvents: "none" }
    : {}

  const magneticStyle: React.CSSProperties = {
    transition: "transform 260ms cubic-bezier(0.16, 1, 0.3, 1)",
    willChange: "transform",
    ...disabledStyle,
  }

  if ("href" in rest && rest.href) {
    const { href, ...anchorRest } = rest as AnchorProps
    return (
      <a
        ref={ref as React.RefObject<HTMLAnchorElement>}
        href={href}
        aria-disabled={disabled}
        {...anchorRest}
        style={{ ...magneticStyle, ...(anchorRest.style ?? {}) }}
        onMouseMove={onMouseMove}
        onMouseLeave={onMouseLeave}
      >
        {children}
      </a>
    )
  }

  const btnRest = rest as ButtonProps
  return (
    <button
      ref={ref as React.RefObject<HTMLButtonElement>}
      {...btnRest}
      disabled={disabled}
      style={{ ...magneticStyle, ...(btnRest.style ?? {}) }}
      onMouseMove={onMouseMove}
      onMouseLeave={onMouseLeave}
    >
      {children}
    </button>
  )
}
```

Key changes:
- `disabled` extracted from `rest` in `BaseProps` so it doesn't leak into the spread
- `onMouseMove` early-returns when disabled, killing the magnetic effect
- `disabledStyle` applies `opacity: 0.4`, `cursor: not-allowed`, and `pointerEvents: none` (blocks clicks without JS)
- `<button>` gets the native `disabled` prop; `<a>` gets `aria-disabled` since anchors have no native disabled state — `pointerEvents: none` handles click blocking there
- `disabledStyle` is merged before `anchorRest.style` / `btnRest.style` so callers can still override if needed

